// Some portions generated by Co-Pilot
import { describe, it, expect } from "vitest";
import { render, screen } from "@testing-library/react";
import CommonCard from "../index";

const mockData = {
  title: "Test Title",
  description: "This is a test description.",
  href: "/test-link",
  button: "Click Me",
};

describe("CommonCard", () => {
  it("renders a compact action card without nesting buttons inside its link", () => {
    const { container } = render(
      <CommonCard data={mockData} variant="modern" />,
    );
    expect(screen.getByRole("article")).toBeInTheDocument();
    const link = screen.getByRole("link", { name: "Click Me" });
    expect(link).toHaveAttribute("href", "/test-link");
    expect(link).not.toHaveAttribute("target");
    expect(container.querySelector("a button")).not.toBeInTheDocument();
    expect(link.querySelector("polyline")).toHaveAttribute(
      "points",
      "12 5 19 12 12 19",
    );
  });

  it("uses an external-style arrow only for external destinations", () => {
    render(
      <CommonCard
        data={{ ...mockData, href: "https://example.com" }}
        variant="modern"
      />,
    );
    const link = screen.getByRole("link", { name: "Click Me" });
    expect(link).toHaveAttribute("href", "https://example.com");
    expect(link.querySelector("polyline")).toHaveAttribute(
      "points",
      "7 7 17 7 17 17",
    );
  });

  it("renders the title, description, and button", () => {
    render(<CommonCard data={mockData} />);
    expect(screen.getByText("Test Title")).toBeInTheDocument();
    expect(screen.getByText("This is a test description.")).toBeInTheDocument();
    expect(
      screen.getByRole("button", { name: "Click Me" }),
    ).toBeInTheDocument();
  });

  it("renders the correct link for the button", () => {
    render(<CommonCard data={mockData} />);
    const links = screen.getAllByRole("link");
    // There should be only one link in this render
    expect(links[0]).toHaveAttribute("href", "/test-link");
  });

  it("applies the correct classes", () => {
    render(<CommonCard data={mockData} />);
    const card = screen.getAllByTestId("common-card")[0];
    expect(card).toHaveClass("common-card");
  });
});
